import pathlib,subprocess,os,zipfile,sys
R=pathlib.Path(__file__).resolve().parents[1];S=pathlib.Path(os.environ.get('ANDROID_HOME',str(pathlib.Path.home()/'Library/Android/sdk')));B=S/'build-tools/35.0.0';J=pathlib.Path(os.environ.get('JAVA_HOME','/opt/homebrew/opt/openjdk@17/libexec/openjdk.jdk/Contents/Home'));A=S/'platforms/android-34/android.jar';D=R/'artifacts/v1.10.1/device-test';D.mkdir(exist_ok=True);SERIAL=os.environ.get('ECHOSUDOKU_ADB_SERIAL',os.environ.get('ECHOSODU_ADB_SERIAL','emulator-5556'))
