(D/'AndroidManifest.xml').write_text('<manifest xmlns:android="http://schemas.android.com/apk/res/android" package="com.tankecho.zensudoku.tests"><uses-sdk android:minSdkVersion="26" android:targetSdkVersion="34"/><application android:label="Zen Sudoku Tests"/><instrumentation android:name="com.tankecho.zensudoku.tests.DeviceTests" android:targetPackage="com.tankecho.zensudoku"/><instrumentation android:name="com.tankecho.zensudoku.tests.DemoRun" android:targetPackage="com.tankecho.zensudoku"/><instrumentation android:name="com.tankecho.zensudoku.tests.DemoV14" android:targetPackage="com.tankecho.zensudoku"/><instrumentation android:name="com.tankecho.zensudoku.tests.CaptureV14" android:targetPackage="com.tankecho.zensudoku"/><instrumentation android:name="com.tankecho.zensudoku.tests.DemoV15" android:targetPackage="com.tankecho.zensudoku"/><instrumentation android:name="com.tankecho.zensudoku.tests.VictoryDeviceTests" android:targetPackage="com.tankecho.zensudoku"/><instrumentation android:name="com.tankecho.zensudoku.tests.DemoV16" android:targetPackage="com.tankecho.zensudoku"/><instrumentation android:name="com.tankecho.zensudoku.tests.BlinkDeviceTests" android:targetPackage="com.tankecho.zensudoku"/><instrumentation android:name="com.tankecho.zensudoku.tests.DemoBlink" android:targetPackage="com.tankecho.zensudoku"/><instrumentation android:name="com.tankecho.zensudoku.tests.V17DeviceTests" android:targetPackage="com.tankecho.zensudoku"/><instrumentation android:name="com.tankecho.zensudoku.tests.CaptureV17" android:targetPackage="com.tankecho.zensudoku"/><instrumentation android:name="com.tankecho.zensudoku.tests.PersistenceV17" android:targetPackage="com.tankecho.zensudoku"/><instrumentation android:name="com.tankecho.zensudoku.tests.SafV17" android:targetPackage="com.tankecho.zensudoku"/><instrumentation android:name="com.tankecho.zensudoku.tests.LegacyV17" android:targetPackage="com.tankecho.zensudoku"/><instrumentation android:name="com.tankecho.zensudoku.tests.DemoV17" android:targetPackage="com.tankecho.zensudoku"/><instrumentation android:name="com.tankecho.zensudoku.tests.V18DeviceTests" android:targetPackage="com.tankecho.zensudoku"/><instrumentation android:name="com.tankecho.zensudoku.tests.DemoV18" android:targetPackage="com.tankecho.zensudoku"/><instrumentation android:name="com.tankecho.zensudoku.tests.V19DeviceTests" android:targetPackage="com.tankecho.zensudoku"/><instrumentation android:name="com.tankecho.zensudoku.tests.DemoV19" android:targetPackage="com.tankecho.zensudoku"/><instrumentation android:name="com.tankecho.zensudoku.tests.MedalDeviceTests" android:targetPackage="com.tankecho.zensudoku"/><instrumentation android:name="com.tankecho.zensudoku.tests.DemoV191" android:targetPackage="com.tankecho.zensudoku"/><instrumentation android:name="com.tankecho.zensudoku.tests.SolarDeviceTests" android:targetPackage="com.tankecho.zensudoku"/><instrumentation android:name="com.tankecho.zensudoku.tests.DemoV192" android:targetPackage="com.tankecho.zensudoku"/><instrumentation android:name="com.tankecho.zensudoku.tests.TutorialDeviceTests" android:targetPackage="com.tankecho.zensudoku"/><instrumentation android:name="com.tankecho.zensudoku.tests.DemoV110" android:targetPackage="com.tankecho.zensudoku"/></manifest>')
run([B/'aapt','package','-f','-M',D/'AndroidManifest.xml','-I',A,'-F',D/'unsigned.apk'])
run([J/'bin/javac','-source','8','-target','8','-bootclasspath',str(B/'core-lambda-stubs.jar')+':'+str(A),'-d',D/'classes',R/'tools/DeviceTests.java',R/'tools/DemoRun.java',R/'tools/DemoV14.java',R/'tools/CaptureV14.java',R/'tools/DemoV15.java',R/'tools/VictoryDeviceTests.java',R/'tools/DemoV16.java',R/'tools/BlinkDeviceTests.java',R/'tools/DemoBlink.java',R/'tools/V17DeviceTests.java',R/'tools/CaptureV17.java',R/'tools/PersistenceV17.java',R/'tools/SafV17.java',R/'tools/LegacyV17.java',R/'tools/DemoV17.java',R/'tools/V18DeviceTests.java',R/'tools/DemoV18.java',R/'tools/V19DeviceTests.java',R/'tools/DemoV19.java',R/'tools/MedalDeviceTests.java',R/'tools/DemoV191.java',R/'tools/DemoV110.java',R/'tools/TutorialDeviceTests.java',R/'tools/SolarDeviceTests.java',R/'tools/DemoV192.java'])
run([B/'d8','--min-api','26','--lib',A,'--output',D/'dex',*sorted((D/'classes').rglob('*.class'))])
with zipfile.ZipFile(D/'unsigned.apk','a',zipfile.ZIP_DEFLATED) as z:z.write(D/'dex/classes.dex','classes.dex')
run([B/'zipalign','-f','4',D/'unsigned.apk',D/'aligned.apk'])
key=pathlib.Path.home()/'.local/share/zen-sudoku/signing'
run([B/'apksigner','sign','--ks',key/'release.jks','--ks-pass','file:'+str(key/'password'),'--out',D/'tests.apk',D/'aligned.apk'])
