if '--build-only' in sys.argv:raise SystemExit(0)
runner='com.tankecho.zensudoku.tests/.DemoV19' if '--demo' in sys.argv else 'com.tankecho.zensudoku.tests/.V19DeviceTests'
result=subprocess.run([str(S/'platform-tools/adb'),'-s',SERIAL,'shell','am','instrument','-w',runner],capture_output=True,text=True,check=True)
